(float)$variant['price'],2) }}</option>@endforeach</select>@endif<div class="buy-row"><input type="number" name="quantity" min="1" max="999" value="1" aria-label="Cantidad" @disabled($unavailable)><button class="add" @disabled($unavailable)>{{ $unavailable ? 'Agotado' : 'Agregar' }}</button></div></form></article>@empty <div class="empty">No hay productos para mostrar.</div>@endforelse</div></section>
