@push('scripts')
<script>(()=>{const search=document.getElementById('product-search'),buttons=document.querySelectorAll('.category-filter'),cards=[...document.querySelectorAll('[data-product]')],count=document.getElementById('product-count');let category='';const apply=()=>{const term=(search?.value||'').toLowerCase();let visible=0;cards.forEach(card=>{const show=(!category||card.dataset.category===category)&&card.dataset.name.includes(term);card.hidden=!show;if(show)visible++});count.textContent=`${visible} disponibles`};search?.addEventListener('input',apply);buttons.forEach(button=>button.addEventListener('click',()=>{category=button.dataset.category;document.querySelectorAll('.chip').forEach(chip=>chip.classList.toggle('active',chip.dataset.category===category));apply()}));const toast=document.createElement('div');toast.className='cart-toast';document.body.append(toast);let toastTimer;const showToast=(message,error=false)=>{toast.textContent=message;toast.classList.toggle('error',error);toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('show'),2600)};document.querySelectorAll('[data-cart-form]').forEach(form=>form.addEventListener('submit',async event=>{event.preventDefault();const button=form.querySelector('.add'),label=button.textContent;button.disabled=true;button.textContent='Agregando…';try{const response=await fetch(form.action,{method:'POST',headers:{Accept:'application/json','X-Requested-With':'XMLHttpRequest'},body:new FormData(form),credentials:'same-origin'});const payload=await response.json();if(!response.ok)throw new Error(payload.message||'No fue posible agregar el producto.');document.querySelectorAll('.cart-count').forEach(item=>item.textContent=payload.cart_count);button.textContent='Agregado ✓';showToast(payload.message)}catch(error){button.textContent=label;showToast(error.message||'No fue posible agregar el producto.',true)}finally{setTimeout(()=>{button.disabled=false;if(button.textContent==='Agregado ✓')button.textContent=label},700)}}))})();</script>
@endpush
